import { createHash, randomBytes, timingSafeEqual, scrypt as _scrypt } from 'crypto';
import { promisify } from 'util';

const scrypt = promisify(_scrypt);

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

interface User {
  id: string;
  email: string;
  passwordHash: string;
  role?: string;
}

interface RateLimitEntry {
  count: number;
  firstAttempt: number;
}

export class AuthService implements IAuthService {
  private users: Map<string, User> = new Map();
  private rateLimits: Map<string, RateLimitEntry> = new Map();
  private readonly HASH_SALT_LENGTH = 16;
  private readonly HASH_KEY_LENGTH = 64;
  private readonly HASH_OPTIONS = { N: 16384, r: 8, p: 1 }; // scrypt parameters
  private readonly RATE_LIMIT_WINDOW_MS = 60 * 1000; // 1 minute
  private readonly MAX_LOGIN_ATTEMPTS = 5;

  constructor() {
    // Seed with a dummy user for testing
    this.hashPassword('password123').then(hash => {
      this.users.set('test@example.com', {
        id: 'user1',
        email: 'test@example.com',
        passwordHash: hash,
        role: 'admin',
      });
    });
  }

  public async hashPassword(password: string): Promise<string> {
    const salt = randomBytes(this.HASH_SALT_LENGTH);
    const derivedKey = await scrypt(password, salt, this.HASH_KEY_LENGTH, this.HASH_OPTIONS);
    return `${salt.toString('hex')}:${(derivedKey as Buffer).toString('hex')}`;
  }

  public async verifyPassword(password: string, hash: string): Promise<boolean> {
    const [saltHex, derivedKeyHex] = hash.split(':');
    if (!saltHex || !derivedKeyHex) return false;

    const salt = Buffer.from(saltHex, 'hex');
    const storedDerivedKey = Buffer.from(derivedKeyHex, 'hex');

    const newDerivedKey = await scrypt(password, salt, this.HASH_KEY_LENGTH, this.HASH_OPTIONS);
    return timingSafeEqual(storedDerivedKey, newDerivedKey as Buffer);
  }

  public async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    // A simplified, non-cryptographically secure token generation for demonstration.
    // In a real application, use a library like 'jsonwebtoken' for proper JWTs with signing.
    const header = { alg: 'HS256', typ: 'JWT' };
    const encodedHeader = Buffer.from(JSON.stringify(header)).toString('base64url');
    const encodedPayload = Buffer.from(JSON.stringify({ ...payload, iat: Math.floor(Date.now() / 1000) })).toString('base64url');

    // Simple HMAC-like signature using SHA256 for demonstration. Not a real JWT signature.
    const signature = createHash('sha256').update(`${encodedHeader}.${encodedPayload}.${secret}`).digest('base64url');

    return `${encodedHeader}.${encodedPayload}.${signature}`;
  }

  private checkRateLimit(ip: string): { allowed: boolean; retryAfter?: number } {
    const now = Date.now();
    let entry = this.rateLimits.get(ip);

    if (!entry || now - entry.firstAttempt > this.RATE_LIMIT_WINDOW_MS) {
      entry = { count: 1, firstAttempt: now };
      this.rateLimits.set(ip, entry);
      return { allowed: true };
    }

    entry.count++;
    this.rateLimits.set(ip, entry);

    if (entry.count > this.MAX_LOGIN_ATTEMPTS) {
      const retryAfter = Math.ceil((entry.firstAttempt + this.RATE_LIMIT_WINDOW_MS - now) / 1000);
      return { allowed: false, retryAfter };
    }

    return { allowed: true };
  }

  public async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const { email, password, ip } = request;

    if (!email || !password) {
      return { status: 400, body: { message: 'Email and password are required.' } };
    }

    if (ip) {
      const { allowed, retryAfter } = this.checkRateLimit(ip);
      if (!allowed) {
        return { status: 429, body: { message: `Too many login attempts. Please try again after ${retryAfter} seconds.` } };
      }
    }

    const user = this.users.get(email);

    if (!user || !(await this.verifyPassword(password, user.passwordHash))) {
      return { status: 401, body: { message: 'Invalid credentials.' } };
    }

    // In a real app, the secret would come from environment variables
    const token = await this.generateToken({ id: user.id, email: user.email, role: user.role }, 'super-secret-key');

    // Clear rate limit on successful login
    if (ip) {
      this.rateLimits.delete(ip);
    }

    return { status: 200, body: { message: 'Login successful.', token } };
  }
}

