import * as bcrypt from 'bcrypt';
import * as jwt from 'jsonwebtoken';
import * as crypto from 'crypto';

// --- Rate Limiting Configuration ---
const MAX_LOGIN_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 5 * 60 * 1000; // 5 minutes
const ATTEMPT_WINDOW_MS = 1 * 60 * 1000; // 1 minute

// In-memory store for rate limiting attempts
interface LoginAttempt {
  count: number;
  lastAttempt: number;
  lockoutUntil: number;
}
const loginAttempts = new Map<string, LoginAttempt>();

// --- Interface Contract ---
export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

// --- AuthService Implementation ---
export class AuthService implements IAuthService {
  private readonly BCRYPT_SALT_ROUNDS = 12;
  private readonly JWT_EXPIRATION = '15m'; // Short-lived access token

  /**
   * Hashes a plain text password using bcrypt.
   * @param password The plain text password.
   * @returns A promise that resolves to the hashed password.
   */
  public async hashPassword(password: string): Promise<string> {
    return bcrypt.hash(password, this.BCRYPT_SALT_ROUNDS);
  }

  /**
   * Verifies a plain text password against a bcrypt hash.
   * Uses bcrypt's built-in timing-safe comparison.
   * @param password The plain text password.
   * @param hash The hashed password.
   * @returns A promise that resolves to true if the password matches, false otherwise.
   */
  public async verifyPassword(password: string, hash: string): Promise<boolean> {
    return bcrypt.compare(password, hash);
  }

  /**
   * Generates a JSON Web Token (JWT) for the given payload.
   * @param payload The data to include in the token.
   * @param secret The secret key for signing the token.
   * @returns A promise that resolves to the generated JWT string.
   */
  public async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    // Ensure the secret is treated as a Buffer for crypto operations if it's a string
    const secretBuffer = Buffer.from(secret, 'utf8');
    // Use crypto.timingSafeEqual for secret comparison if it were a direct comparison,
    // but jwt.sign handles its own internal secret usage.
    return new Promise((resolve, reject) => {
      jwt.sign(payload, secretBuffer, { expiresIn: this.JWT_EXPIRATION }, (err, token) => {
        if (err) return reject(err);
        if (!token) return reject(new Error('Failed to generate token.'));
        resolve(token);
      });
    });
  }

  /**
   * Handles user login attempts, including rate limiting.
   * @param request An object containing email, password, and optional IP address.
   * @returns A promise that resolves to an object with status and body.
   */
  public async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const { email, password, ip } = request;

    if (!email || !password) {
      return { status: 400, body: { message: 'Email and password are required.' } };
    }

    const clientIp = ip || 'unknown'; // Default to 'unknown' if IP is not provided

    // --- Rate Limiting Logic ---
    const now = Date.now();
    let attempt = loginAttempts.get(clientIp);

    if (!attempt || now - attempt.lastAttempt > ATTEMPT_WINDOW_MS) {
      // Reset attempts if outside the window or first attempt
      attempt = { count: 1, lastAttempt: now, lockoutUntil: 0 };
    } else {
      attempt.count++;
    }
    loginAttempts.set(clientIp, attempt);

    if (attempt.lockoutUntil > now) {
      return { status: 429, body: { message: 'Too many login attempts. Please try again later.' } };
    }

    if (attempt.count > MAX_LOGIN_ATTEMPTS) {
      attempt.lockoutUntil = now + LOCKOUT_DURATION_MS;
      loginAttempts.set(clientIp, attempt);
      return { status: 429, body: { message: 'Too many login attempts. Account locked for a short period.' } };
    }
    // --- End Rate Limiting Logic ---

    // Simulate user lookup and password verification
    // In a real application, this would involve a database query
    const MOCK_USER_HASH = await this.hashPassword('securePassword123'); // Pre-hashed mock password
    const MOCK_USER_ID = 'user123';
    const MOCK_USER_EMAIL = 'test@example.com';
    const MOCK_USER_ROLE = 'user';

    if (email !== MOCK_USER_EMAIL) {
      // Do not reveal if email exists or not for security
      return { status: 401, body: { message: 'Invalid credentials.' } };
    }

    const isPasswordValid = await this.verifyPassword(password, MOCK_USER_HASH);

    if (!isPasswordValid) {
      return { status: 401, body: { message: 'Invalid credentials.' } };
    }

    // Reset attempts on successful login
    loginAttempts.delete(clientIp);

    // Generate token on successful login
    try {
      const token = await this.generateToken(
        { id: MOCK_USER_ID, email: MOCK_USER_EMAIL, role: MOCK_USER_ROLE },
        'super-secret-jwt-key-for-testing' // In production, this should come from environment variables
      );
      return { status: 200, body: { message: 'Login successful.', token } };
    } catch (error) {
      console.error('Error generating token:', error); // Log internal error
      return { status: 500, body: { message: 'Internal server error during token generation.' } };
    }
  }
}

