export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class Money {
  readonly amount: number;
  readonly currency: string;

  private constructor(amount: number, currency: string) {
    if (amount < 0) {
      throw new Error('Amount cannot be negative.');
    }
    if (!currency || currency.trim() === '') {
      throw new Error('Currency cannot be empty.');
    }
    this.amount = amount;
    this.currency = currency;
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (this.currency !== other.currency) {
      throw new Error('Cannot add Money with different currencies.');
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    if (!(other instanceof Money)) {
      return false;
    }
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string; // Represents productId
  quantity: number;
  price: Money; // Price per unit
}

interface OrderEvent {
  type: string;
  payload: any;
}

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus;
  private _items: OrderItem[];
  private domainEvents: OrderEvent[];

  constructor(id: string, customerId: string) {
    if (!id || !customerId) {
      throw new Error('Order ID and Customer ID are required.');
    }
    this.id = id;
    this.customerId = customerId;
    this._status = 'PENDING';
    this._items = [];
    this.domainEvents = [];
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return this._items;
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new Error('Cannot add items to an order that is not PENDING.');
    }
    if (quantity <= 0) {
      throw new Error('Quantity must be positive.');
    }
    const existingItem = this._items.find(item => item.id === productId && item.price.equals(price));
    if (existingItem) {
      existingItem.quantity += quantity;
    } else {
      this._items.push({ id: productId, quantity, price });
    }
    this.domainEvents.push({ type: 'OrderItemAdded', payload: { orderId: this.id, productId, quantity, price } });
  }

  pay(): void {
    if (this._status !== 'PENDING') {
      throw new Error('Order can only be paid if its status is PENDING.');
    }
    if (this._items.length === 0) {
      throw new Error('Cannot pay an order with no items.');
    }
    this._status = 'PAID';
    this.domainEvents.push({ type: 'OrderPaid', payload: { orderId: this.id, total: this.getTotal() } });
  }

  ship(): void {
    if (this._status !== 'PAID') {
      throw new Error('Order can only be shipped if its status is PAID.');
    }
    this._status = 'SHIPPED';
    this.domainEvents.push({ type: 'OrderShipped', payload: { orderId: this.id } });
  }

  cancel(): void {
    if (this._status === 'SHIPPED' || this._status === 'CANCELLED') {
      throw new Error('Order cannot be cancelled if it is SHIPPED or already CANCELLED.');
    }
    this._status = 'CANCELLED';
    this.domainEvents.push({ type: 'OrderCancelled', payload: { orderId: this.id } });
  }

  getTotal(): Money {
    if (this._items.length === 0) {
      return Money.of(0, 'USD'); // Default currency if no items
    }
    const initialCurrency = this._items[0].price.currency;
    return this._items.reduce((total, item) => {
      const itemTotal = Money.of(item.price.amount * item.quantity, item.price.currency);
      return total.add(itemTotal);
    }, Money.of(0, initialCurrency));
  }

  getDomainEvents(): any[] {
    const events = [...this.domainEvents];
    this.domainEvents = []; // Clear events after retrieval
    return events;
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

// In-memory implementation of IOrderRepository
class InMemoryOrderRepository implements IOrderRepository {
  private orders: Map<string, Order> = new Map();

  async findById(id: string): Promise<Order | null> {
    const order = this.orders.get(id);
    // Deep copy to prevent external modification of the stored object
    // In a real scenario, this would involve rehydrating from a data model
    if (order) {
      const rehydratedOrder = new Order(order.id, order.customerId);
      // Restore internal state
      (rehydratedOrder as any)._status = order.status;
      (rehydratedOrder as any)._items = order.items.map(item => ({
        ...item,
        price: Money.of(item.price.amount, item.price.currency)
      }));
      return rehydratedOrder;
    }
    return null;
  }

  async save(order: Order): Promise<void> {
    // Store a deep copy to prevent external modification of the stored object
    // In a real scenario, this would involve mapping to a data model for persistence
    const orderToStore = new Order(order.id, order.customerId);
    (orderToStore as any)._status = order.status;
    (orderToStore as any)._items = order.items.map(item => ({
      ...item,
      price: Money.of(item.price.amount, item.price.currency)
    }));
    this.orders.set(order.id, orderToStore);
  }
}

export const orderRepository: IOrderRepository = new InMemoryOrderRepository();

