type OrderDomainEvent = OrderCreatedEvent | OrderItemAddedEvent | OrderPaidEvent | OrderShippedEvent | OrderCancelledEvent;

export class Order {
  public readonly id: string;
  public readonly customerId: string;
  private _status: OrderStatus;
  private _items: OrderItem[];
  private _domainEvents: OrderDomainEvent[];

  public constructor(id: string, customerId: string) {
    if (!id || id.trim() === '') {
      throw new Error('Order ID cannot be empty.');
    }
    if (!customerId || customerId.trim() === '') {
      throw new Error('Customer ID cannot be empty.');
    }
    this.id = id;
    this.customerId = customerId;
    this._status = 'PENDING';
    this._items = [];
    this._domainEvents = [{ type: 'OrderCreated', orderId: this.id, customerId: this.customerId, occurredAt: new Date() }];
  }

  public get status(): OrderStatus {
    return this._status;
  }

  public get items(): ReadonlyArray<OrderItem> {
    return this._items;
  }

  public addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new Error('Cannot add items to an order that is not PENDING.');
    }
    if (quantity <= 0) {
      throw new Error('Quantity must be greater than zero.');
    }
    if (!productId || productId.trim() === '') {
      throw new Error('Product ID cannot be empty.');
    }

    const existingItem = this._items.find(item => item.id === productId && item.price.equals(price));
    if (existingItem) {
      // For simplicity, we'll just update quantity if item with same product ID and price exists.
      // In a real system, you might want to prevent this or have more complex merging logic.
      existingItem.quantity += quantity;
    } else {
      this._items.push({ id: productId, quantity, price });
    }
    this._domainEvents.push({ type: 'OrderItemAdded', orderId: this.id, productId, quantity, price, occurredAt: new Date() });
  }

  public pay(): void {
    if (this._status !== 'PENDING') {
      throw new Error(`Cannot pay an order with status ${this._status}.`);
    }
    if (this._items.length === 0) {
      throw new Error('Cannot pay an empty order.');
    }
    this._status = 'PAID';
    this._domainEvents.push({ type: 'OrderPaid', orderId: this.id, total: this.getTotal(), occurredAt: new Date() });
  }

  public ship(): void {
    if (this._status !== 'PAID') {
      throw new Error(`Cannot ship an order with status ${this._status}.`);
    }
    this._status = 'SHIPPED';
    this._domainEvents.push({ type: 'OrderShipped', orderId: this.id, occurredAt: new Date() });
  }

  public cancel(reason?: string): void {
    if (this._status === 'SHIPPED' || this._status === 'CANCELLED') {
      throw new Error(`Cannot cancel an order with status ${this._status}.`);
    }
    this._status = 'CANCELLED';
    this._domainEvents.push({ type: 'OrderCancelled', orderId: this.id, reason, occurredAt: new Date() });
  }

  public getTotal(): Money {
    if (this._items.length === 0) {
      return Money.of(0, 'USD'); // Default currency if no items, or infer from first item
    }

    const firstCurrency = this._items[0].price.currency;
    const totalAmount = this._items.reduce((sum, item) => {
      if (item.price.currency !== firstCurrency) {
        throw new Error('All items in an order must have the same currency.');
      }
      return sum + (item.quantity * item.price.amount);
    }, 0);

    return Money.of(totalAmount, firstCurrency);
  }

  public getDomainEvents(): ReadonlyArray<OrderDomainEvent> {
    return this._domainEvents;
  }

  // Clear events after they have been dispatched/persisted
  public clearDomainEvents(): void {
    this._domainEvents = [];
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

// In-memory implementation of IOrderRepository for demonstration
class InMemoryOrderRepository implements IOrderRepository {
  private readonly orders = new Map<string, Order>();

  public async findById(id: string): Promise<Order | null> {
    const order = this.orders.get(id);
    if (!order) {
      return null;
    }
    // Deep copy to ensure aggregate integrity (prevent external modification)
