    (rehydratedOrder as any)._status = order.status; // Bypass readonly for rehydration
    (rehydratedOrder as any)._items = order.items.map(item => ({ ...item, price: Money.of(item.price.amount, item.price.currency) }));
    (rehydratedOrder as any)._domainEvents = []; // Events are transient, not rehydrated
    return rehydratedOrder;
  }

