export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class CircuitBreaker {
  private _state: CircuitState = 'CLOSED';
  private failureCount: number = 0;
  private lastFailureTime: number = 0;
  private readonly options: Required<CircuitBreakerOptions>;

  constructor(options?: CircuitBreakerOptions) {
    this.options = {
      failureThreshold: options?.failureThreshold ?? 5,
      resetTimeoutMs: options?.resetTimeoutMs ?? 5000,
    };
  }

  get state(): CircuitState {
    return this._state;
  }

  getState(): CircuitState {
    return this._state;
  }

  recordSuccess(): void {
    if (this._state === 'HALF_OPEN') {
      this._state = 'CLOSED';
      this.failureCount = 0;
    } else if (this._state === 'CLOSED') {
      this.failureCount = 0; // Reset consecutive failures
    }
  }

  recordFailure(): void {
    if (this._state === 'CLOSED') {
      this.failureCount++;
      if (this.failureCount >= this.options.failureThreshold) {
        this._state = 'OPEN';
        this.lastFailureTime = Date.now();
      }
    } else if (this._state === 'HALF_OPEN') {
      this._state = 'OPEN';
      this.lastFailureTime = Date.now();
    }
  }

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this._state === 'OPEN') {
      if (Date.now() - this.lastFailureTime > this.options.resetTimeoutMs) {
        this._state = 'HALF_OPEN';
      } else {
        throw new Error('CircuitBreaker is OPEN');
      }
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }
}

export class ApiError extends Error {
  readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ApiError.prototype);
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly circuitBreaker: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.circuitBreaker = circuitBreaker ?? new CircuitBreaker();
  }

  private async makeRequest<T>(
    url: string,
    method: string,
    options?: RequestOptions,
  ): Promise<T> {
    const controller = new AbortController();
    const timeout = options?.timeoutMs ?? 10000; // Default to 10 seconds
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, {
        method: method,
        headers: options?.headers,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        const errorBody = await response.text();
        throw new ApiError(
          `API request failed: ${response.status} ${errorBody}`,
          response.status,
        );
      }

      return (await response.json()) as T;
    } catch (error: any) {
      clearTimeout(timeoutId);
      if (error.name === 'AbortError') {
        throw new Error(`Request timed out after ${timeout}ms`);
      }
      throw error;
    }
  }

  get<T>(url: string, options?: RequestOptions): Promise<T> {
