export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class CircuitBreaker {
  private _state: CircuitState = 'CLOSED';
  private failureCount: number = 0;
  private lastFailureTime: number = 0;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;

  constructor(options?: CircuitBreakerOptions) {
    this.failureThreshold = options?.failureThreshold ?? 3;
    this.resetTimeoutMs = options?.resetTimeoutMs ?? 5000;
  }

  public get state(): CircuitState {
    return this.getState();
  }

  public getState(): CircuitState {
    if (this._state === 'OPEN' && Date.now() - this.lastFailureTime > this.resetTimeoutMs) {
      this._state = 'HALF_OPEN';
    }
    return this._state;
  }

  public recordSuccess(): void {
    if (this._state === 'HALF_OPEN' || this._state === 'CLOSED') {
      this._state = 'CLOSED';
      this.failureCount = 0;
      this.lastFailureTime = 0;
    }
  }

  public recordFailure(): void {
    this.failureCount++;
    if (this._state === 'HALF_OPEN') {
      this._state = 'OPEN';
      this.lastFailureTime = Date.now();
    } else if (this._state === 'CLOSED' && this.failureCount >= this.failureThreshold) {
      this._state = 'OPEN';
      this.lastFailureTime = Date.now();
    }
  }

  public async execute<T>(action: () => Promise<T>): Promise<T> {
    const currentState = this.getState();
    if (currentState === 'OPEN') {
      throw new Error('CircuitBreaker is OPEN. Requests are blocked.');
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error: unknown) {
      this.recordFailure();
      throw error;
    }
  }
}

export class ApiError extends Error {
  public readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ApiError.prototype);
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly circuitBreaker: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.circuitBreaker = circuitBreaker ?? new CircuitBreaker();
  }

  public async get<T>(url: string, options?: RequestOptions): Promise<T> {
    const action = async (): Promise<T> => {
      const controller = new AbortController();
      const timeout = options?.timeoutMs;

      const fetchOptions: RequestInit = {
        method: 'GET',
        headers: options?.headers,
        signal: controller.signal,
      };

      const timeoutPromise = new Promise<never>((_, reject) => {
        if (typeof timeout === 'number' && timeout > 0) {
          setTimeout(() => {
            controller.abort();
            reject(new Error(`Request timed out after ${timeout}ms`));
          }, timeout);
        }
      });

      try {
        const response = await Promise.race([
          fetch(url, fetchOptions),
          timeoutPromise,
        ]);

        if (!response.ok) {
          const errorText = await response.text();
          throw new ApiError(
            `API request failed with status ${response.status}: ${errorText}`,
            response.status
          );
        }

        const data: unknown = await response.json();
        return data as T; // Assuming T matches the JSON structure, runtime validation would be ideal here.
      } catch (error: unknown) {
        if (error instanceof Error && error.name === 'AbortError') {
          throw new Error(`Request to ${url} was aborted.`);
        }
        throw error;
      }
    };

    return this.circuitBreaker.execute(action);
  }
}
